+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+const value = objWrapper({
+    prop1: strWrapper
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+
+// Expected: { prop1: "hello" }. Force a mismatch diagnostic that prints the actual type of Test.
+declare const t: Test;
+const expected: { prop1: "hello" } = t;
diff --git a/repro60573/show.js b/repro60573/show.js
new file mode 100644
index 000000000..c7fbbbd83
--- /dev/null
+++ b/repro60573/show.js
@@ -0,0 +1,22 @@
+// usage: node show.js <path-to-typescript.js> <file.ts>
+// Prints how the checker displays `type Test` (what hover / error messages show).
+const path = require('path');
+const ts = require(path.resolve(process.argv[2]));
+const file = path.resolve(process.argv[3]);
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, types: [] });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+let shown;
+ts.forEachChild(sf, n => {
+  if (ts.isTypeAliasDeclaration(n) && n.name.text === 'Test') {
+    const t = checker.getTypeAtLocation(n.name);
+    shown = checker.typeToString(t, undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias);
+    const p = t.getProperty('prop1');
+    console.log(`typescript ${ts.version}`);
+    console.log(`  expected: type Test = { prop1: "hello"; }`);
+    console.log(`  actual:   type Test = ${shown}`);
+    if (p) console.log(`  (getTypeOfSymbol(Test.prop1) = ${checker.typeToString(checker.getTypeOfSymbol(p))})`);
+  }
+});
+if (shown !== '{ prop1: "hello"; }') { console.log('BUG: displayed type of Test is wrong'); process.exit(1); }
+console.log('OK');
diff --git a/repro60573/show2.js b/repro60573/show2.js
