@@ -0,0 +1,16 @@
+// usage: node show2.js <typescript.js> <file.ts> <order: print-first|prop-first>
+const ts = require(require('path').resolve(process.argv[2]));
+const file = require('path').resolve(process.argv[3]);
+const order = process.argv[4] || 'print-first';
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, types: [] });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+console.log('typescript', ts.version, order);
+ts.forEachChild(sf, n => {
+  if (ts.isTypeAliasDeclaration(n) && n.name.text === 'Test') {
+    const t = checker.getTypeAtLocation(n.name);
+    const print = () => console.log('  typeToString(Test) =', checker.typeToString(t, undefined, ts.TypeFormatFlags.NoTruncation));
+    const prop = () => { const p = t.getProperty('prop1'); console.log('  typeof Test.prop1  =', checker.typeToString(checker.getTypeOfSymbol(p))); };
+    if (order === 'print-first') { print(); prop(); print(); } else { prop(); print(); }
+  }
+});
